    public Object parseWsTrade(Object trade, Object... optionalArgs)
    {
        //
        //     {
        //         "symbol":"SPOT_ADA_USDT",
        //         "timestamp":1618820361552,
        //         "price":1.27988,
        //         "size":300,
        //         "side":"BUY",
        //         "source":0
        //     }
        // private trade
        //    {
        //     "msgType": 0,  // execution report
        //     "symbol": "SPOT_BTC_USDT",
        //     "clientOrderId": 0,
        //     "orderId": 54774393,
        //     "type": "MARKET",
        //     "side": "BUY",
        //     "quantity": 0.0,
        //     "price": 0.0,
        //     "tradeId": 56201985,
        //     "executedPrice": 23534.06,
        //     "executedQuantity": 0.00040791,
        //     "fee": 2.1E-7,
        //     "feeAsset": "BTC",
        //     "totalExecutedQuantity": 0.00040791,
        //     "avgPrice": 23534.06,
        //     "status": "FILLED",
        //     "reason": "",
        //     "orderTag": "default",
        //     "totalFee": 2.1E-7,
        //     "feeCurrency": "BTC",
        //     "totalRebate": 0,
        //     "rebateCurrency": "USDT",
        //     "visible": 0.0,
        //     "timestamp": 1675406261689,
        //     "reduceOnly": false,
        //     "maker": false
        //   }
        //
        Object market = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        String marketId = this.safeString(trade, "symbol");
        market = this.safeMarket(marketId, market);
        Object symbol = ((Map<String, Object>)market).get("symbol");
        String price = this.safeString2(trade, "executedPrice", "price");
        String amount = this.safeString2(trade, "executedQuantity", "size");
        String cost = Precise.stringMul(price, amount);
        String side = this.safeStringLower(trade, "side");
        Long timestamp = this.safeInteger(trade, "timestamp");
        Boolean maker = (Boolean) this.safeBool(trade, "maker");
        String takerOrMaker = null;
        if (!java.util.Objects.equals(maker, null))
        {
            takerOrMaker = ((Boolean.TRUE.equals(maker))) ? "maker" : "taker";
        }
        String type = this.safeStringLower(trade, "type");
        Object fee = null;
        Double feeCost = this.safeNumber(trade, "fee");
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Object finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "cost", finalFeeCost );
                put( "currency", Woo.this.safeCurrencyCode(Woo.this.safeString(trade, "feeCurrency")) );
            }};
        }
        final Object finalTakerOrMaker = takerOrMaker;
        final Object finalFee = fee;
        return this.safeTrade(new HashMap<String, Object>() {{
            put( "id", Woo.this.safeString(trade, "tradeId") );
            put( "timestamp", timestamp );
            put( "datetime", Woo.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "side", side );
            put( "price", price );
            put( "amount", amount );
            put( "cost", cost );
            put( "order", Woo.this.safeString(trade, "orderId") );
            put( "takerOrMaker", finalTakerOrMaker );
            put( "type", type );
            put( "fee", finalFee );
            put( "info", trade );
        }}, market);
    }

